head.script:
scwin.onpageload = function() {
    //GridView의 초기 개인화 스타일 저장하기
	$p.local.setItem("P00198_init_grid", grd_main.getCurrentGridStyle());


    // 기존에 저장된 GridView의 스타일을 저장.
    let gridStyle = $p.local.getItem("P00198_grd_style");

    if (gridStyle) {

        grd_main.setGridStyle(gridStyle);

        //로그 출력
        //$c.frame.printExampleLog("저장된 GridView의 개인화 스타일이 적용되었습니다.", txa_log, false);

        console.log("저장된 GridView의 개인화 스타일이 적용되었습니다.");
    } else {
        //로그 출력
        //$c.frame.printExampleLog("저장된 GridView의 개인화 스타일이 없습니다.", txa_log, false);
        console.log("저장된 GridView의 개인화 스타일이 없습니다.");
    }
};

/**
 * 버튼 [저장] 클릭 시
 * Trigger 'btn_save' 의 onclick 이벤트 핸들러
 */
scwin.btn_save_onclick = function(e) {    
    // 현재 gridView 스타일 정보 가져오기
	var grd_style = grd_main.getCurrentGridStyle();

    // localStorage에 gridView의 style 저장
	$p.local.setItem("P00198_grd_style", grd_style);

    //로그 출력
    var strLog = "GridView 개인화 스타일 저장 완료";
    //$c.frame.printExampleLog(strLog, txa_log, false);
    console.log(strLog);
};

/**
 * 버튼 [불러오기] 클릭 시
 * Trigger 'btn_load' 의 onclick 이벤트 핸들러
 */
scwin.btn_load_onclick = function(e) {
    // localStorage에 저장한 gridView 스타일 정보 가져오기
    var grd_style = $p.local.getItem("P00198_grd_style");

    var strLog;
    if (!grd_style) {
        strLog = "저장된 GridView의 개인화 스타일이 없습니다.";
    } else {
        // 현재 gridView의 개인화 스타일 적용
        grd_main.setGridStyle(grd_style);
        strLog = "GridView에 저장된 개인화 스타일이 적용되었습니다.";
    }

    //로그 출력
    //$c.frame.printExampleLog(strLog, txa_log, false);
    console.log(strLog);
};

/**
 * 버튼 [삭제] 클릭 시
 * Trigger 'btn_clear' 의 onclick 이벤트 핸들러
 */
scwin.btn_clear_onclick = function(e) {
    // 저장된 스타일 정보 제거
    $p.local.removeItem("P00198_grd_style");

    // 화면 파일의 GridView 개인화 스타일을 적용합니다.
    grd_main.setGridStyle($p.local.getItem("P00198_init_grid"));

    //로그 출력
    var strLog = "저장된 GridView의 개인화 스타일이 삭제되었습니다.\nGridView의 개인화 스타일이 초기화되었습니다.";
    //$c.frame.printExampleLog(strLog, txa_log, false);
    console.log(strLog);
};

/**
 * 버튼 [초기화] 클릭 시
 * Trigger 'btn_init' 의 onclick 이벤트 핸들러
 */
scwin.btn_init_onclick = function(e) {

    // 화면 파일의 GridView 개인화 스타일을 적용합니다.
    grd_main.setGridStyle($p.local.getItem("P00198_init_grid"));

    //로그 출력
    var strLog = "GridView의 개인화 스타일이 초기화되었습니다.(저장된 개인화 스타일은 삭제되지 않습니다.)";
    $c.frame.printExampleLog(strLog, txa_log, false);
};

/**
 * textarea의 로그 삭제
 */
scwin.btn_clearLog_onclick = function (e) {
    let strTargetId = this.getUserData("userData1");
    let cmpTarget;
    if (strTargetId) {
        cmpTarget = $p.getComponentById(strTargetId) || txa_log;
    } else {
        cmpTarget = txa_log;
    }
    //textarea value를 빈문자열로 할당.
    cmpTarget.setValue("");
};

	scwin.fireClick = function(node){            
		if( document.createEventObject ) {
			node.fireEvent('oncontextmenu') ;  
		} else if( document.createEvent ) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('contextmenu', true, false);
			node.dispatchEvent(evt);    
		} else if (typeof node.contextmenu == 'function' ) {
			node.oncontextmenu();  
		}
	}
	scwin.rightClick = function(id){
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireClick(el);
	}         
	scwin.setVal = function(){
		WebSquare.wUnit.getDomById('grd_main_contextMenu_list').querySelectorAll('div')[1].click()
	}   	
	scwin.checkVal = function(){
		return WebSquare.wUnit.getDomById('grd_main_column11').offsetWidth == 0;
	}   
	scwin.unitTest = function(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_init').click()");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("set", "scwin.rightClick('grd_main_column11')");
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("set", "scwin.setVal()");
		WebSquare.wUnit.addCommand("pause", "1000");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_save').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_load').click()");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
